SELECT t.name AS "Nome do Departamento", SUM(CASE WHEN u.suspended = 0 THEN 1 ELSE 0 END) AS "Usuários Ativos", SUM(CASE WHEN u.suspended = 1 THEN 1 ELSE 0 END) AS "Usuários Inativos" FROM mdl_user AS u LEFT JOIN mdl_tool_tenant_user AS tu ON tu.userid = u.id LEFT JOIN mdl_tool_tenant AS t ON t.id = tu.tenantid WHERE u.deleted = 0 AND t.name IS NOT NULL AND t.name NOT IN ('Saber Senac') GROUP BY t.name ORDER BY "Nome do Departamento" ASC;
